@startuml

class Product {
  + name : string
  + description : string
  + netPrice : float
}

class Country {
  + vatRate : float
  + currency : string
  + conversionRateToEuro : float
}

class Representative {
  + firstName : string
  + lastName : string
  + socialSecurityNumber : string
  + telephoneNumber : string
  + emailAddress : string
}

class Customer {
  + name : string
  + address : string
  + telephoneNumber : string
  + emailAddress : string
}

class Order {
  + id : string
  + quantity : int
  + orderDate : date
  + desiredDeliveryDate : date
}

class Manufacturer {
  + name : string
}

Product "*" -- "1" Manufacturer : manufacturedBy
Product "*" -- "1" Country : soldIn
Representative "1" -- "1" Country : responsibleFor
Customer "*" -- "*" Country : resellsIn
Representative "1" -- "*" Order : places
Order "*" -- "1" Product
Order "*" -- "1" Customer

@enduml

